import assert from "node:assert/strict";
import fs from "node:fs";
const seed=JSON.parse(fs.readFileSync("data/research/sacred-art-b56-53-classi-curated-source-seed.json","utf8"));
const script=fs.readFileSync("scripts/research/sacred_art_b56_53_hero_selector.py","utf8");
const dates=seed.dates;
assert.equal(dates.length,53);
assert.equal(dates.filter(x=>x.protected_approval?.user_choice_approved).length,10);
const holy=dates.find(x=>x.date==="2026-04-02");
const ember=dates.find(x=>x.date==="2026-05-27");
assert.equal(holy.protected_approval.artist,"Philippe de Champaigne");
assert.equal(holy.protected_approval.title,"La Petite Cène");
assert.equal(holy.protected_approval.catalogue_id,ember.protected_approval.catalogue_id);
assert.equal(holy.protected_approval.catalogue_id,"ART-hilippe-de-hampaigne-a-etite-ne");
assert.equal(holy.superseded_date_approval_20261019.artist,"Ugolino da Siena");
assert.equal(holy.superseded_date_approval_20261019.catalogue_id,"met-459131");
assert.equal(ember.protected_approval.artist,"Philippe de Champaigne");
assert.equal(ember.protected_approval.title,"La Petite Cène");
assert.ok(holy.excluded_artwork_candidates_by_user.includes("met-459131"));
assert.match(script,/day\["date"\]=="2026-04-02" and pid=="met-459131"/);
assert.match(script,/physical_museum_frame_absent_verified/);
assert.match(script,/gallery_surround_absent_verified/);
assert.match(script,/complete_painted_surface_verified/);
assert.equal(seed.user_decision_updates.at(-1).date_of_user_decision,"2026-10-26");
console.log("PASS: B56 53-date source seed now honors 26 Oct Holy Thursday Champaigne revision and preserves 19 Oct Ugolino history, with photo-release holds.");
